/// Dials the socket of `spec`: its URL with a ws(s) scheme, the call's headers and credential (a fresh
/// `X-Request-Id` unless one is set), and `protocols` offered; its frames read by `read`.
pub(crate) async fn connect<In, Out>(
    inner: &Inner,
    spec: &RequestSpec,
    ov: &Overrides,
    protocols: &[String],
    read: Read<In>,
) -> Result<(TypedWebSocket<In, Out>, RawResponse), Error> {
    let mut url = url_of(inner, spec, ov)?;
    let scheme = if url.scheme() == "https" { "wss" } else { "ws" };
    url.set_scheme(scheme)
        .map_err(|()| Error::Config("the base_url cannot carry a WebSocket".into()))?;
    let token = token_of(inner, ov).await;
    let headers = headers_of(inner, spec, ov, token.as_deref())?;
    let mut request = url.as_str().into_client_request().map_err(transport)?;
    request.headers_mut().extend(headers);
    if !protocols.is_empty() {
        let offered = HeaderValue::from_str(&protocols.join(", "))
            .map_err(|_| Error::Config("a subprotocol is not valid in a header".into()))?;
        request
            .headers_mut()
            .insert("sec-websocket-protocol", offered);
    }
    let config = WebSocketConfig::default().max_message_size(Some(MAX_MESSAGE));
    let (socket, response) =
        tokio_tungstenite::connect_async_with_config(request, Some(config), false)
            .await
            .map_err(transport)?;
    let raw = RawResponse {
        status: response.status().as_u16(),
        url,
        headers: response.headers().clone(),
        body: Bytes::new(),
    };
    let socket = TypedWebSocket {
        socket,
        read,
        on_message: Vec::new(),
        on_close: Vec::new(),
        on_error: Vec::new(),
        closed_by: None,
        ended: false,
        cancel: ov.cancel.clone(),
        keepalive: inner.ws_keepalive.map(|every| Keepalive {
            every,
            due: tokio::time::Instant::now() + every,
            pinged: false,
        }),
        sends: PhantomData,
    };
    Ok((socket, raw))
}

